mapper.select:
SELECT l.log_id, l.source_id, l.source_name, l.run_status, l.fetched_count, l.inserted_count,
       l.matched_count, l.error_msg, l.start_time, l.end_time
FROM bid_crawl_log l

     AND l.source_id = #{sourceId}
     AND l.source_name LIKE CONCAT('%', #{sourceName}, '%')
     AND l.run_status = #{runStatus}
     AND l.error_msg LIKE CONCAT('%', #{errorMsg}, '%')
     AND l.start_time >= #{params.beginStartTime}
     AND l.start_time <= #{params.endStartTime}

ORDER BY l.log_id DESC

SELECT l.log_id, l.source_id, l.source_name, l.run_status, l.fetched_count, l.inserted_count,
       l.matched_count, l.error_msg, l.start_time, l.end_time
FROM bid_crawl_log l WHERE l.log_id = #{logId}
